// Substitua a configuração atual por esta versão otimizada para mobile
class PatrimonialScanner {
    constructor() {
        this.scanner = null;
        this.isScanning = false;
        this.currentCameraId = null;
        this.cameras = [];
        this.scannerModal = null;
        this.initialized = false;
    }

    async initialize() {
        if (this.initialized) return;
        console.log("🔄 Inicializando scanner CEAD para mobile...");
        
        try {
            // Verificar se estamos em mobile
            this.isMobile = this.detectMobile();
            
            await this.waitForHtml5Qrcode();
            this.setupEvents();
            await this.loadCameras();
            this.initialized = true;
            console.log("✅ Scanner mobile pronto");
        } catch (e) {
            console.error("❌ Erro init:", e);
            this.disableButton("Scanner indisponível");
        }
    }

    detectMobile() {
        return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    }

    async getOptimizedConfig() {
        if (this.isMobile) {
            // Configuração otimizada para mobile
            return {
                fps: 15,
                qrbox: { width: 250, height: 150 }, // Menor para melhor performance
                aspectRatio: 1.333, // Proporção comum em smartphones
                focusMode: "continuous",
                formatsToSupport: [
                    Html5QrcodeSupportedFormats.CODE_128,
                    Html5QrcodeSupportedFormats.CODE_39,
                    Html5QrcodeSupportedFormats.EAN_13,
                    Html5QrcodeSupportedFormats.EAN_8,
                    Html5QrcodeSupportedFormats.UPC_A,
                    Html5QrcodeSupportedFormats.UPC_E,
                    Html5QrcodeSupportedFormats.QR_CODE
                ]
            };
        } else {
            // Configuração para desktop
            return {
                fps: 10,
                qrbox: { width: 300, height: 200 },
                aspectRatio: 1.777,
                focusMode: "continuous",
                formatsToSupport: [
                    Html5QrcodeSupportedFormats.CODE_128,
                    Html5QrcodeSupportedFormats.CODE_39,
                    Html5QrcodeSupportedFormats.EAN_13,
                    Html5QrcodeSupportedFormats.UPC_A,
                    Html5QrcodeSupportedFormats.QR_CODE
                ]
            };
        }
    }

    async start() {
        if (this.isScanning) return;
        
        const viewport = document.getElementById("scanner-viewport");
        viewport.innerHTML = '<div class="scanner-loading"><i class="bi bi-camera"></i><br>Iniciando câmera...</div>';
        
        try {
            this.scanner = new Html5Qrcode("scanner-viewport");
            const cameraConfig = await this.getCamera();
            const scanConfig = await this.getOptimizedConfig();

            await this.scanner.start(
                cameraConfig,
                scanConfig,
                (decodedText) => this.onScanSuccess(decodedText),
                (errorMessage) => {
                    // Ignora erros de leitura contínua
                    console.log("Scan em progresso:", errorMessage);
                }
            );

            this.isScanning = true;
            this.updateStatus("📦 Aponte para o código de barras");
            this.hideLoading();
            
        } catch (error) {
            console.error("Erro ao iniciar scanner:", error);
            this.handleScannerError(error);
        }
    }

    handleScannerError(error) {
        let errorMessage = "Erro na câmera";
        
        if (error.includes("NotAllowedError")) {
            errorMessage = "Permissão da câmera negada";
        } else if (error.includes("NotFoundError")) {
            errorMessage = "Nenhuma câmera encontrada";
        } else if (error.includes("NotSupportedError")) {
            errorMessage = "Recurso não suportado";
        } else if (error.includes("NotReadableError")) {
            errorMessage = "Câmera já em uso";
        }
        
        this.updateStatus(`❌ ${errorMessage}`);
        this.showErrorUI(errorMessage);
    }

    showErrorUI(message) {
        const viewport = document.getElementById("scanner-viewport");
        viewport.innerHTML = `
            <div class="scanner-error-message">
                <i class="bi bi-camera-video-off" style="font-size: 3rem;"></i>
                <p class="mt-3">${message}</p>
                <button class="btn btn-light btn-sm mt-2" onclick="patrimonialScanner.manualEntry()">
                    <i class="bi bi-keyboard"></i> Digitar Manualmente
                </button>
            </div>
        `;
    }

    // NOVO MÉTODO PARA ENTRADA MANUAL MELHORADA
    manualEntry() {
        this.stop();
        if (this.scannerModal) {
            this.scannerModal.hide();
        }
        
        // Aguardar o modal fechar completamente
        setTimeout(() => {
            const input = document.getElementById('numero_bem');
            if (input) {
                // Remover qualquer atributo que impeça a digitação
                input.removeAttribute('readonly');
                input.removeAttribute('disabled');
                
                // Focar e abrir teclado
                input.focus();
                
                // Disparar eventos para forçar teclado em mobile
                const event = new Event('touchstart', { bubbles: true });
                input.dispatchEvent(event);
                
                // Tentativa adicional para iOS
                setTimeout(() => {
                    input.setSelectionRange(0, 0);
                    input.click();
                }, 100);
            }
        }, 300);
    }

    onScanSuccess(decodedText) {
        const cleanCode = this.cleanCode(decodedText);
        if (!cleanCode) return;

        console.log("✅ Código lido:", cleanCode);
        
        // Feedback visual e sonoro
        this.beep();
        if (navigator.vibrate) {
            navigator.vibrate([100, 50, 100]);
        }
        
        this.showResult(cleanCode);
        
        // Parar scanner após leitura bem-sucedida
        this.stop();
    }

    cleanCode(code) {
        if (!code) return null;
        
        // Limpar e validar o código
        let cleaned = code.trim()
            .replace(/[^\w\-\s\.]/g, '') // Mantém letras, números, hífen, ponto e espaço
            .replace(/\s+/g, ' ')        // Normaliza espaços
            .toUpperCase();
            
        // Validação básica - pelo menos 3 caracteres
        return cleaned.length >= 3 ? cleaned : null;
    }
}

// Inicialização melhorada
document.addEventListener("DOMContentLoaded", () => {
    window.patrimonialScanner = new PatrimonialScanner();
    
    // Inicialização mais agressiva para mobile
    if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
        setTimeout(() => patrimonialScanner.initialize(), 500);
    } else {
        setTimeout(() => patrimonialScanner.initialize(), 1000);
    }
});